# Change the sheet's today. Validate first so a bad date is a 400, not masked by a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveToday
  govern: [ transaction ]
  next: autoClose
# Once the new today is set: every open period past its to-date plus the grace days closes.
autoClose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithToday
  govern: [ transaction ]
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;

public class SaveToday {
    public void save(@Val Sheet sheet, @Val LocalDate today, SheetRepository repository) {
        repository.saveToday(sheet.id(), today);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> todayOut)
            throws InvalidTodayException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            todayOut.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException();
        }
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Once the sheet's today is changed: closes every open period whose to-date plus the sheet's grace
 * days is before the new today, in order of their to-dates, exactly as a close by hand would, each
 * recording PERIOD_CLOSED with auto=yes as it closes. Nothing closes while the grace days are off.
 */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, @Val LocalDate today, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings,
            HttpServletRequest request, Audit audit) {
        Settings sheetSettings = settings.find(sheet.id());
        Sheet now = new Sheet(sheet.id(), today, sheet.archived());
        List<Period> due = periods.findAll(sheet.id()).stream()
                .filter((p) -> !p.closed() && sheetSettings.pastGrace(p.to(), today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            Period closed = ClosePeriod.fix(now, period, false, periods, people, claims, log, rates, settings);
            if (closed == null) continue; // another request closed it first
            audit.record("PERIOD_CLOSED sheet=" + sheet.id() + " by=" + Audit.user(request)
                    + " period=" + closed.name() + " total=" + closed.closedTotal().setScale(2).toPlainString()
                    + " auto=yes");
        }
    }
}

