package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total (by person id,
 * in the order they were added), and the sheet's claimed-total, due-total and overdue-total.
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    /** A person's figures: their name, claimed, due-total (n/a when none) and overdue-total. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean sameFigures(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /**
     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
     * and SETTLED, but not an unbound OPEN one dated within one of their holds) added up; their due-total the figures of those claims added up, skipping n/a (a live due is the greater of the floor on its date and its rate figure plus the late
     * charge it gains on {@code today}), and
     * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
     * figure or has one under the grade in force on its date when that is another grade, or
     * has one dated on or before today (under a rate that has since ended), held to the sheet's cap. Each claim
     * takes the rate of the grade in force on its date. The
     * sheet's totals add these up, skipping n/a; with three or more figures, the due-total and
     * overdue-total leave out the single highest and the single lowest.
     */
    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
            RateRepository rates, Settings settings) {
        List<Rate> all = rates.findAll(sheetId);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!claim.counts(person.heldOn(claim.getDate(), today), today)) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
                if (figure != null) due = due.add(figure);
                if (figure != null && overdue(claim, today)) overdue = overdue.add(figure);
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
                // So is one dated on or before today, found under a rate that has since ended.
                if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
            }
            boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            due = settings.capped(due, today);
            if (!none) dues.add(due);
            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due),
                    show(overdue)));
        }
        return new Rollup(figures, show(claimedTotal), show(trimmed(dues)), show(trimmed(overdues)));
    }

    /** People's figures added up: with three or more, the single highest and single lowest left out. */
    private static BigDecimal trimmed(List<BigDecimal> values) {
        List<BigDecimal> sorted = new ArrayList<>(values);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Whether a claim is overdue on {@code today}: open (OPEN or PENDING) and past its due-by. */
    private static boolean overdue(Claim claim, LocalDate today) {
        return claim.isOpen() && today != null && claim.getDueBy() != null && claim.getDueBy().isBefore(today);
    }

    /**
     * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
     * figures changed (a person new since counts as changed), then a TOTALS line when any of the
     * sheet's three totals changed.
     */
    public List<String> changesSince(Rollup before, String sheetId, String user) {
        List<String> lines = new ArrayList<>();
        String head = " sheet=" + sheetId + " by=" + user;
        people.forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!claimedTotal.equals(before.claimedTotal()) || !dueTotal.equals(before.dueTotal())
                || !overdueTotal.equals(before.overdueTotal())) {
            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
                    + " overdue-total=" + overdueTotal);
        }
        return lines;
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: their due-total now (the figures of their claims that count, added
 * up, skipping n/a; n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
 * figure, has one under another grade in force on its date, or has one dated on or before today (under a
 * rate that has since ended); held to the sheet's cap; each claim at its date's grade's rate; an overdue claim's late charge on top), as the screen shows it. Every claim of theirs that counts is bound to its rate figure now
 * (a live one before the floor), never its late charge nor the floor;
 * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
 * and the due-total and the sheet's today are kept as the last statement's.
 * <p>
 * Taken as of a date (on or before the sheet's today, and not before the person was added), it is
 * taken as the sheet stood at the end of that date: every change made while the sheet's today was
 * on or before it counts (the rates, settings, the person's grades, holds and retirement, each
 * claim's status, settled due and statement binding), every later change does not, and the date
 * stands in for the sheet's today in every figure. That date is kept as the statement's date.
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, @Val StatementInput input, ClaimRepository claims,
            ClaimLogRepository logs, RateRepository rates, SettingsRepository settings, PersonRepository people,
            Out<Statement> statementOut) throws InvalidStatementException {
        LocalDate asOf = input.asOf();
        if (asOf != null && asOf.isAfter(sheet.today())) {
            throw new InvalidStatementException("A statement is taken as of a date on or before today");
        }
        if (asOf != null && !person.addedBy(asOf)) {
            throw new InvalidStatementException(person.getName() + " was not yet added on " + asOf);
        }
        LocalDate today = asOf != null ? asOf : sheet.today();
        List<Rate> all = asOf != null ? rates.findAsOf(sheet.id(), asOf) : rates.findAll(sheet.id());
        Settings sheetSettings = asOf != null ? settings.findAsOf(sheet.id(), asOf) : settings.find(sheet.id());
        Person then = asOf != null ? people.asOf(person, asOf) : person;
        Map<Long, ClaimLogRepository.Line> lines = asOf != null ? logs.linesOn(sheet.id(), asOf) : null;
        Map<Long, ClaimRepository.Binding> bindings = asOf != null ? claims.bindingsOn(sheet.id(), asOf) : null;
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        for (Claim live : claims.findByPerson(sheet.id(), person.getId())) {
            Claim claim = live;
            if (asOf != null) {
                ClaimLogRepository.Line line = lines.get(live.getId());
                ClaimRepository.Binding binding = bindings.get(live.getId());
                claim = line == null ? null : live.asThen(line.status(),
                        line.status() == ClaimStatus.SETTLED ? line.due() : null,
                        binding != null && binding.stated(), binding == null ? null : binding.statedDue());
            }
            boolean counts = claim != null && claim.counts(then.heldOn(claim.getDate(), today), today);
            if (counts) {
                counted++;
                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
                String grade = then.gradeOn(claim.getDate());
                BigDecimal figure = claim.getSettledDue() != null ? claim.getSettledDue()
                        : ClaimFigure.of(claim, all, grade, sheetSettings, today);
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(then.gradeOn(today))) fixed = true;
                // So is one dated on or before today, found under a rate that has since ended.
                if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
                // The due-total carries the late charge and the floor; the claim is bound to the rate figure under them.
                BigDecimal due = ClaimFigure.withLate(claim, all, grade, sheetSettings, today);
                if (due != null) total = total.add(due);
                live.bind(true, figure);
            } else {
                live.bind(false, null);
            }
            claims.save(live);
        }
        String dueTotal = Rate.inForce(all, then.gradeOn(today), today).isEmpty() && !fixed
                ? "n/a" : sheetSettings.capped(total, today).toPlainString();
        person.setStatements(person.getStatementCount() + 1, dueTotal, today);
        people.saveStatements(person);
        statementOut.set(new Statement(dueTotal, counted, asOf));
    }
}

